// The Cloudflare Worker entry: the Next.js app built by OpenNext, plus the hourly Cron
// Trigger (wrangler.jsonc "triggers") that makes scheduled follow-ups due.
// Bundled by wrangler at deploy time, after `opennextjs-cloudflare build`.

// @ts-ignore: generated by the build
import { default as handler } from "./.open-next/worker.js";
import { runFollowUpCron } from "./src/lib/followups-cron";

interface Env {
  DB: Parameters<typeof runFollowUpCron>[0];
  FOLLOW_UP_DAILY_LIMIT?: string;
}

export default {
  fetch: handler.fetch,

  async scheduled(_controller: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    ctx.waitUntil(
      runFollowUpCron(env.DB, Date.now(), Math.max(1, Number(env.FOLLOW_UP_DAILY_LIMIT) || 30))
        .then((r) => console.log("[follow-ups]", JSON.stringify(r)))
        .catch((e) => console.error("[follow-ups] failed:", e)),
    );
  },
};
